        return _bind_plain(select, schema, where, indices=None)

    return _bind_aggregate(select, schema, where, group_indices, has_aggregate)


def _bind_plain(
    select: _Select, schema: Schema, where: tuple | None, indices: tuple[int, ...] | None
) -> _Plan:
