        aggregate=True,
        where=where,
        limit=select.limit,
        indices=None,
        source_order=None,
        grouped=grouped,
        group_indices=group_indices,
        items=tuple(items),
        result_schema=result_schema,
        result_order=result_order,
    )


def _bind_aggregate_item(func: str, arg: tuple, schema: Schema) -> _AggSpec:
